/**
 * Imports season data generated by scripts/build-season-*-data.mjs into the
 * structured tables. The JSON is downloaded from the public repository at run
 * time instead of being bundled into this project.
 *
 * Run `previewSeason2Import` first: it checks the data against the live tables
 * and reports what would be added without writing anything.
 */
const SEASON_2_DATA_URL =
  'https://raw.githubusercontent.com/Lets-Queue-Club/lets-queue-club.github.io/main/data/season-2/season-2.json'

const SEASON_IMPORT_FORMAT = 'lets-queue-club.season-import'
const SEASON_IMPORT_FORMAT_VERSION = 1

// Columns that identify a row. Rows whose key already exists are skipped, so an
// import can be re-run safely (e.g. Champions shared between seasons).
const IMPORT_TABLE_KEYS = {
  Teams: ['ID'],
  Players: ['PUUID'],
  Matches: ['Game ID'],
  MatchTeams: ['Game ID', 'Team ID'],
  MatchParticipants: ['Game ID', 'PUUID'],
  Champions: ['ID'],
}

function previewSeason2Import() {
  return importSeasonData(SEASON_2_DATA_URL, { dryRun: true })
}

function importSeason2() {
  return importSeasonData(SEASON_2_DATA_URL, { dryRun: false })
}

function importSeasonData(url, { dryRun = true } = {}) {
  const lock = LockService.getScriptLock()
  lock.waitLock(30000)
  try {
    const data = fetchSeasonData(url)
    const spreadsheetId = getSpreadsheet().getId()
    const plan = planSeasonImport(spreadsheetId, data)
    const summary = {
      season: data.season,
      dryRun,
      tables: plan.map(({ name, imported, added, skipped }) => ({ name, imported, added, skipped })),
    }

    const requests = plan
      .filter((table) => table.rows.length > 0)
      .map((table) => ({
        appendCells: {
          tableId: table.tableId,
          rows: table.rows,
          fields: 'userEnteredValue',
        },
      }))
    if (!dryRun && requests.length > 0) {
      // One batchUpdate is atomic: if any table fails, nothing is written.
      batchUpdateSpreadsheet(spreadsheetId, requests)
    }

    console.log(JSON.stringify(summary, null, 2))
    return summary
  } finally {
    lock.releaseLock()
  }
}

function fetchSeasonData(url) {
  const response = UrlFetchApp.fetch(url, { muteHttpExceptions: true })
  const status = response.getResponseCode()
  if (status !== 200) {
    throw new Error(`Downloading ${url} failed with HTTP ${status}.`)
  }
  const data = JSON.parse(response.getContentText())
  if (
    data.format !== SEASON_IMPORT_FORMAT ||
    data.formatVersion !== SEASON_IMPORT_FORMAT_VERSION
  ) {
    throw new Error(
      `Unsupported import file: expected ${SEASON_IMPORT_FORMAT} v${SEASON_IMPORT_FORMAT_VERSION}.`,
    )
  }
  return data
}

function planSeasonImport(spreadsheetId, data) {
  const { sheets = [] } = Sheets.Spreadsheets.get(spreadsheetId, {
    fields: 'sheets(properties(title),tables(tableId,name,range,columnProperties))',
  })
  const liveTables = new Map(
    sheets.flatMap((sheet) =>
      (sheet.tables ?? []).map((table) => [table.name, { ...table, sheetTitle: sheet.properties.title }]),
    ),
  )

  const problems = []
  const targets = []
  for (const [name, rows] of Object.entries(data.tables)) {
    const live = liveTables.get(name)
    const importColumns = data.tableColumns[name]
    const keyColumns = IMPORT_TABLE_KEYS[name]
    if (!live) {
      problems.push(`Table "${name}" does not exist in the spreadsheet.`)
      continue
    }
    if (!keyColumns) {
      problems.push(`No key columns are defined for table "${name}" in IMPORT_TABLE_KEYS.`)
      continue
    }
    const liveIndex = new Map(
      (live.columnProperties ?? []).map((column) => [column.columnName, column.columnIndex ?? 0]),
    )
    const missing = importColumns.filter((column) => !liveIndex.has(column))
    if (missing.length > 0) {
      problems.push(`Table "${name}" is missing columns: ${missing.join(', ')}.`)
      continue
    }
    targets.push({ name, rows, live, liveIndex, importColumns, keyColumns })
  }
  if (problems.length > 0) {
    throw new Error(`Import aborted; nothing was written.\n${problems.join('\n')}`)
  }

  const { valueRanges = [] } = targets.length
    ? Sheets.Spreadsheets.Values.batchGet(spreadsheetId, {
        ranges: targets.map((target) => toA1Range(target.live.sheetTitle, target.live.range)),
        majorDimension: 'ROWS',
        valueRenderOption: 'UNFORMATTED_VALUE',
      })
    : {}
  if (valueRanges.length !== targets.length) {
    throw new Error('Sheets API did not return every requested table range.')
  }

  return targets.map((target, index) => {
    const keyOf = (getValue) => JSON.stringify(target.keyColumns.map((column) => String(getValue(column) ?? '')))
    const existing = new Set(
      (valueRanges[index].values ?? [])
        .slice(1)
        .map((row) => keyOf((column) => row[target.liveIndex.get(column)]))
        .filter((key) => key !== keyOf(() => '')),
    )
    const width = target.live.range.endColumnIndex - (target.live.range.startColumnIndex ?? 0)
    const newRows = target.rows.filter((row) => !existing.has(keyOf((column) => row[column])))
    return {
      name: target.name,
      tableId: target.live.tableId,
      imported: target.rows.length,
      added: newRows.length,
      skipped: target.rows.length - newRows.length,
      rows: newRows.map((row) => {
        const cells = Array.from({ length: width }, () => ({}))
        for (const column of target.importColumns) {
          cells[target.liveIndex.get(column)] = toCellData(row[column])
        }
        return { values: cells }
      }),
    }
  })
}

function toCellData(value) {
  if (value === '' || value === null || value === undefined) return {}
  if (typeof value === 'number') return { userEnteredValue: { numberValue: value } }
  if (typeof value === 'boolean') return { userEnteredValue: { boolValue: value } }
  // stringValue keeps text such as numeric taglines from being parsed as numbers.
  return { userEnteredValue: { stringValue: String(value) } }
}
